SELECT com11_form_mapping_multi_id AS form_mapping_multi_id,
       com11_company_id            AS company_id,
       com11_sys_kind_cd           AS sys_kind_code,
       com11_sys_detail_cd         AS sys_detail_code,
       com11_link_cd               AS link_code,
       com11_content               AS content,
       com11_note                  AS note
  FROM com11_form_mapping_multi
 WHERE com11_company_id = #{companyId}
   AND com11_sys_kind_cd = #{kindCode}
   AND com11_sys_detail_cd = #{detailCode}
   AND com11_link_cd = #{linkCode}

SELECT com11_company_id
  FROM com11_form_mapping_multi
 WHERE com11_form_mapping_multi_id = #{formMappingMultiId}

mapper.update:
UPDATE com11_form_mapping_multi
   SET com11_content = #{content}
 WHERE com11_form_mapping_multi_id = #{formMappingMultiId}
